<div class="page-head"><div><h1 class="h2">Contratti e piani ricorrenti</h1><p class="text-secondary mb-0">Piani di servizio e visite previste. La riprogrammazione delle visite mantiene lo storico del contratto.</p></div><a class="btn btn-primary" href="/app/contratti/nuovo">＋ Nuovo contratto</a></div>
<?php if(!$records): ?><div class="card border-0 shadow-sm"><div class="empty-state"><strong>Nessun contratto registrato</strong><p class="mt-1 mb-3">Crea il primo piano ricorrente e le visite previste verranno generate automaticamente.</p><a class="btn btn-primary" href="/app/contratti/nuovo">Crea contratto</a></div></div><?php else: ?><div class="table-wrap"><table class="table table-hover align-middle"><thead><tr><th>Contratto</th><th>Cliente</th><th>Periodo</th><th>Visite completate</th><th>Stato</th><th></th></tr></thead><tbody><?php foreach($records as $c): ?><tr><td><strong><?= e($c['numero']) ?></strong><br><small><?= e($c['titolo']) ?></small></td><td><?= e($c['cliente']) ?></td><td><?= e(date('d/m/Y',strtotime($c['data_inizio']))) ?> – <?= e($c['data_fine']?date('d/m/Y',strtotime($c['data_fine'])):'aperto') ?></td><td><?= (int)$c['visite_completate'] ?> / <?= (int)$c['totale_visite'] ?></td><td><span class="badge rounded-pill text-bg-light"><?= e(ucfirst(str_replace('_',' ',$c['stato']))) ?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="/app/contratti/<?= (int)$c['id'] ?>">Apri piano</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
